6	1	Pedido	Finalizado	Vendas	SELECT\nE.RAZAO_SOCIAL AS EMPRESA,\nE.LOGOMARCA,\nM.MOVIMENTO_ID,\nC.RAZAO_SOCIAL as CLIENTE,\nC.FONE_GERAL,\nTRIM(BOTH ', -' FROM CONCAT_WS(', ', C.ENDERECO_LOGRADOURO, C.ENDERECO_NUMERO, C.ENDERECO_BAIRRO) || \n  CASE WHEN C.ENDERECO_CEP IS NOT NULL THEN ' - ' || C.ENDERECO_CEP ELSE '' END) AS ENDERECO,\nP.NOME,\nI.QT_MOVIMENTO,\nI.VL_PRODUTO,\nI.QT_MOVIMENTO * I.VL_PRODUTO AS TOTAL, \nM.VL_MOVIMENTO\nFROM MOVIMENTO M \nINNER JOIN MOVIMENTO_ITEM I ON M.MOVIMENTO_ID = I.MOVIMENTO_ID\nINNER JOIN PRODUTO P ON P.PRODUTO_ID = I.PRODUTO_ID\nINNER JOIN CADASTRO C ON C.CADASTRO_ID = M.CADASTRO_ID\nINNER JOIN EMPRESA E ON E.EMPRESA_ID = M.EMPRESA_ID\nWHERE M.MOVIMENTO_ID = {{movimento_id}}\n\n\n\n	\N	{"bands": {"detail": {"height": 5, "bgColor": "#ffffff", "visible": true, "components": [{"h": 5, "w": 70, "x": 0, "y": 0, "id": "1wve6525", "type": "text", "style": {"bold": false, "align": "left", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 9, "underline": false, "borderColor": "#cccccc"}, "content": "{nome}"}, {"h": 5, "w": 9, "x": 95, "y": 0, "id": "fc54vxwr", "type": "text", "style": {"bold": false, "align": "right", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 9, "underline": false, "borderColor": "#cccccc"}, "format": "number", "content": "{qt_movimento}", "decimals": 2}, {"h": 1, "w": 189, "x": 0, "y": 5, "id": "n87nkhjk", "type": "line", "color": "#cccccc", "thickness": 1, "orientation": "horizontal"}, {"h": 5, "w": 16, "x": 120, "y": 0, "id": "1cowttor", "type": "text", "style": {"bold": false, "align": "right", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 9, "underline": false, "borderColor": "#cccccc"}, "format": "number", "content": "{vl_produto}", "decimals": 2}, {"h": 5, "w": 20, "x": 168, "y": 0, "id": "mk6ynpl0", "type": "text", "style": {"bold": f