8	1	Pedido Bobina	Status: Não Finalizado,  Sem ajuste de tamanho	Vendas	SELECT\n    E.EMPRESA_ID,\n\tE.RAZAO_SOCIAL AS EMPRESA,\n\tE.LOGOMARCA,\n    TRIM(BOTH ', -' FROM CONCAT_WS(', ', E.ENDERECO_LOGRADOURO, E.ENDERECO_NUMERO, E.ENDERECO_BAIRRO) || CASE WHEN E.ENDERECO_CEP IS NOT NULL THEN ' - ' || E.ENDERECO_CEP ELSE '' END) AS ENDERECO_EMPRESA,\n\tM.MOVIMENTO_ID,\n    I.QT_MOVIMENTO * I.VL_PRODUTO AS TOTAL, \n\tCOALESCE(CONCAT_WS(' - ', NULLIF(TRIM(C.RAZAO_SOCIAL), ''), NULLIF(TRIM(C.CNPJ), '')), '') AS CLIENTE,\n\tTRIM(BOTH ', -' FROM CONCAT_WS(', ', C.ENDERECO_LOGRADOURO, C.ENDERECO_NUMERO, C.ENDERECO_BAIRRO) || CASE WHEN C.ENDERECO_CEP IS NOT NULL THEN ' - ' || C.ENDERECO_CEP ELSE '' END) AS ENDERECO_CLIENTE,\n\tF.NOME AS FUNCIONARIO,\n\tP.NOME AS PRODUTO,\n\tI.QT_MOVIMENTO,\n\tI.VL_UND_PRODUTO,\n\tI.VL_DESCONTO,\n\tI.VL_PRODUTO\nFROM MOVIMENTO M\nINNER JOIN MOVIMENTO_ITEM I ON M.MOVIMENTO_ID = I.MOVIMENTO_ID\nINNER JOIN CADASTRO C ON C.CADASTRO_ID = M.CADASTRO_ID\nINNER JOIN EMPRESA E ON E.EMPRESA_ID = M.EMPRESA_ID\nINNER JOIN FUNCIONARIO F ON F.FUNCIONARIO_ID = M.FUNCIONARIO_ID\nINNER JOIN PRODUTO P ON P.PRODUTO_ID = I.PRODUTO_ID \nWHERE M.MOVIMENTO_ID = {{movimento_id}}	\N	{"bands": {"detail": {"height": 5, "bgColor": "transparent", "visible": true, "components": [{"h": 3, "w": 50, "x": 1, "y": 0, "id": "xhtzbrz6", "type": "text", "style": {"bold": false, "align": "left", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 7, "underline": false, "borderColor": "#cccccc"}, "content": "{produto}"}, {"h": 3, "w": 10, "x": 55, "y": 0, "id": "ryhqxspz", "type": "text", "style": {"bold": false, "align": "right", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 7, "underline": false, "borderColor": "#cccccc"}, "content": "{qt_movimento}"}, {"h": 3, "w": 15, "x": 67, "y": 0, "id": "k2n3b2yl", "type": "text", "style": {"bold": false, "align": "right", "co