20260529002500	{"-- Create sys_config table for database connection details and backup parameters\nCREATE TABLE IF NOT EXISTS sys_config (\n    id UUID PRIMARY KEY DEFAULT '00000000-0000-0000-0000-000000000000'::uuid,\n    db_server_host TEXT NOT NULL DEFAULT 'localhost',\n    db_server_port TEXT NOT NULL DEFAULT '5432',\n    db_name TEXT NOT NULL DEFAULT 'postgres',\n    db_port TEXT NOT NULL DEFAULT '5432',\n    db_version TEXT NOT NULL DEFAULT '1.15.0',\n    backup_folder_path TEXT NOT NULL DEFAULT '',\n    backup_periodicity TEXT NOT NULL DEFAULT 'manual',\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    -- Constraint to enforce a single settings row\n    CONSTRAINT only_one_row CHECK (id = '00000000-0000-0000-0000-000000000000'::uuid)\n)","-- Create sys_backup_log table for tracking backup histories\nCREATE TABLE IF NOT EXISTS sys_backup_log (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    backup_type TEXT NOT NULL, -- 'system' or 'database'\n    status TEXT NOT NULL,      -- 'success', 'failed', 'pending', 'in_progress'\n    file_name TEXT,\n    file_size_bytes BIGINT,\n    error_message TEXT,\n    started_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    completed_at TIMESTAMP WITH TIME ZONE\n)","-- Index for querying backup logs by type and completion date\nCREATE INDEX IF NOT EXISTS idx_sys_backup_log_type_completed \nON sys_backup_log (backup_type, completed_at DESC)","-- Enable RLS (Row Level Security) if needed or just keep open for admin\nALTER TABLE sys_config ENABLE ROW LEVEL SECURITY","ALTER TABLE sys_backup_log ENABLE ROW LEVEL SECURITY","-- Simple policies (allow all authenticated/admin actions or anonymous in local mode)\nCREATE POLICY \\"Allow read/write sys_config for all users\\" ON sys_config \n    FOR ALL USING (true) WITH CHECK (true)","CREATE POLICY \\"Allow read/write sys_backup_log for all users\\" ON sys_backup_log \n    FOR ALL USING (true) WITH CHECK (true)","-- Insert initial default configuration row\nINSERT INTO sys_config (id, db_server_host, db_server_port, db_name, db_port, db_version, backup_folder_path, backup_periodicity)\nVALUES ('00000000-0000-0000-0000-000000000000'::uuid, 'localhost', '5432', 'postgres', '5432', '1.15.0', '', 'manual')\nON CONFLICT (id) DO NOTHING"}	backup_schema	\N	\N	\N
20260529003500	{"-- Add backup_time, system_folder_path, and supabase_folder_path columns to sys_config table\nALTER TABLE sys_config ADD COLUMN IF NOT EXISTS backup_time TEXT NOT NULL DEFAULT '03:00'","ALTER TABLE sys_config ADD COLUMN IF NOT EXISTS system_folder_path TEXT NOT NULL DEFAULT ''","ALTER TABLE sys_config ADD COLUMN IF NOT EXISTS supabase_folder_path TEXT NOT NULL DEFAULT ''"}	backup_time	\N	\N	\N
